script:
// Excel 导出 - 固定列宽示例
// 查询数据
var data = db.select("select id, username, email, real_name as '真实姓名', create_time as '创建时间' from sys_user where is_del = 0 limit 10")

// 定义表头映射
var headers = {
    "id": "ID",
    "username": "用户名",
    "email": "邮箱地址",
    "真实姓名": "真实姓名",
    "创建时间": "创建时间"
}

// 定义固定列宽（字符数）
var columnWidths = {
    "id": 10,
    "username": 15,
    "email": 30,
    "真实姓名": 20,
    "创建时间": 20
}

// 创建配置对象
var config = excel.createConfig("固定宽度导出")
config.setHeaderMap(headers)
config.setColumnWidths(columnWidths)
config.setAutoWidth(false)  // 关闭自动宽度

// 导出为 Excel 并下载
excel.download(data, config)
